// 固定HMCN2原字段与真实RWM typed叶的配对回归；仅同源小叶，无旧静态库或假世界driver。
#include "resident/kernel/continuation_snapshot.hpp"
#include "resident/kernel/world_timeline_codec.hpp"
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0,failures=0;
void check(bool value,const char* label){++checks;if(!value){++failures;std::cerr<<"FAIL "<<label<<'\n';}}
template<class T> T must(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code);return std::move(r.value);}
CanonicalFraction fraction(const std::string& n,const std::string& d){return must(normalize_fraction(n,d));}
void scalar(Bytes& out,std::uint64_t n,unsigned width=8){for(unsigned i=0;i<width;++i)out.push_back(static_cast<std::uint8_t>(n>>(8*i)));}
void string(Bytes& out,const StableId& s,unsigned width){scalar(out,s.size(),width);out.insert(out.end(),s.begin(),s.end());}
void blob(Bytes& out,const Bytes& b){scalar(out,b.size());out.insert(out.end(),b.begin(),b.end());}
void patch(Bytes& bytes,std::size_t at,std::uint64_t n,unsigned width=8){for(unsigned i=0;i<width;++i)bytes.at(at+i)=static_cast<std::uint8_t>(n>>(8*i));}
Bytes moment(Integer tick,const std::string& n,const std::string& d){Bytes out;CodecVisitor c(out);c.field("half_day_tick",tick);c.object("sub_half_day",[&](auto& x){auto a=n,b=d;x.field("numerator",a);return x.field("denominator",b);});must(c.finish());return out;}
Bytes duration(const std::string& n,const std::string& d){Bytes out;CodecVisitor c(out);c.object("value",[&](auto& x){auto a=n,b=d;x.field("numerator",a);return x.field("denominator",b);});must(c.finish());return out;}
ContinuationSnapshot exact(){ContinuationSnapshot s;s.continuation_version=2;s.source_identity.world_id[0]=1;s.source_identity.execution_epoch=77;s.source_identity.revision=8;s.source_identity.tick=2;s.actor_id="player";s.action_id="service:3";s.action_kind="service";s.wallet_id="wallet";s.max_half_days=8;s.max_gross_outflow=100;s.gross_outflow=40;s.stop=RunStop::restored;s.exact_source_moment=WorldMoment{2,fraction("1","3")};s.exact_started_at=WorldMoment{1,fraction("1","4")};s.exact_committed_duration=HalfDayDuration{fraction("1","2")};s.action_started_source=ContinuationStartedSource{"growth","growth_fixed_service_boundary","growth_fixed_service_boundary:5",1};return s;}
ContinuationSnapshot legacy(){ContinuationSnapshot s;s.source_identity.world_id[0]=1;s.source_identity.execution_epoch=7;s.source_identity.revision=8;s.source_identity.tick=8;s.actor_id="actor.player";s.action_id="action:4";s.action_kind="study_skill";s.wallet_id="wallet.player";s.action_start_tick=1;s.started_tick=2;s.max_half_days=8;s.max_gross_outflow=100;s.committed_half_days=3;s.gross_outflow=40;s.stop=RunStop::cancelled;return s;}
struct Layout {Bytes bytes;std::size_t source_length=0,actor_length=0,schema=0,maximum=0,committed_length=0;};
Layout wire(const ContinuationSnapshot& s,const Bytes& now=moment(2,"1","3"),const Bytes& start=moment(1,"1","4"),const Bytes& spent=duration("1","2")){Layout out;auto& b=out.bytes;b={'H','M','C','N',2};b.insert(b.end(),s.source_identity.world_id.begin(),s.source_identity.world_id.end());scalar(b,s.source_identity.revision);out.source_length=b.size();blob(b,now);out.actor_length=b.size();for(const auto* v:{&s.actor_id,&s.action_id,&s.action_kind,&s.wallet_id})string(b,*v,2);for(const auto* v:{&s.action_started_source->domain,&s.action_started_source->kind,&s.action_started_source->id})string(b,*v,2);out.schema=b.size();scalar(b,s.action_started_source->schema,4);blob(b,start);out.maximum=b.size();scalar(b,s.max_half_days);scalar(b,s.max_gross_outflow);out.committed_length=b.size();blob(b,spent);scalar(b,s.gross_outflow);b.push_back(11);return out;}
Bytes legacy_wire(const ContinuationSnapshot& s){Bytes b={'H','M','C','N',1};b.insert(b.end(),s.source_identity.world_id.begin(),s.source_identity.world_id.end());scalar(b,s.source_identity.execution_epoch);scalar(b,s.source_identity.revision);scalar(b,s.source_identity.tick);for(const auto* v:{&s.actor_id,&s.action_id,&s.action_kind,&s.wallet_id})string(b,*v,8);for(auto n:{s.action_start_tick,s.started_tick,s.max_half_days,s.max_gross_outflow,s.committed_half_days,s.gross_outflow,Integer(6)})scalar(b,n);return b;}
}
int main(){try{
    auto s=exact();auto encoded=encode_continuation_snapshot(s);check(encoded.ok,"HMCN2 accepts selected service scope");if(!encoded.ok)return 1;auto bytes=encoded.value;auto independent=wire(s);check(bytes==independent.bytes,"HMCN2 fixed field order u16 IDs u32 schema u8 stop");
    check(encode_continuation_snapshot(s,bytes.size()).ok,"trusted exact size encode accepted");check(decode_continuation_snapshot(bytes,bytes.size()).ok,"trusted exact size decode accepted");for(auto limit:{std::size_t(0),std::size_t(7),bytes.size()-1}){auto refused=encode_continuation_snapshot(s,limit);check(!refused.ok&&refused.error.kind==ErrorKind::internal,"explicit exact encode capacity refusal");auto denied=decode_continuation_snapshot(bytes,limit);check(!denied.ok&&denied.error.kind==ErrorKind::internal,"explicit exact decode capacity refusal");}
    auto back=decode_continuation_snapshot(bytes);check(back.ok&&back.value.continuation_version==2,"HMCN2 round trip version");if(back.ok){const auto& b=back.value;check(b.source_identity.world_id==s.source_identity.world_id&&b.source_identity.revision==8&&b.source_identity.execution_epoch==0,"HMCN2 no persisted execution epoch");check(b.actor_id==s.actor_id&&b.action_id==s.action_id&&b.action_kind==s.action_kind&&b.wallet_id==s.wallet_id,"HMCN2 four identities preserved");check(b.action_started_source&&b.action_started_source->id==s.action_started_source->id&&b.action_started_source->schema==1,"HMCN2 actual Started source preserved");check(b.exact_source_moment&&must(compare_world_moments(*b.exact_source_moment,*s.exact_source_moment))==0&&b.exact_started_at&&must(compare_world_moments(*b.exact_started_at,*s.exact_started_at))==0,"HMCN2 source and scope moments exact");check(b.exact_committed_duration&&must(compare_fractions(b.exact_committed_duration->value,s.exact_committed_duration->value))==0&&b.gross_outflow==40&&b.max_half_days==8&&b.max_gross_outflow==100,"HMCN2 duration and gross unchanged");check(must(encode_continuation_snapshot(b))==bytes,"HMCN2 canonical byte round trip");}
    auto old=legacy();auto old_bytes=must(encode_continuation_snapshot(old));check(old_bytes==legacy_wire(old),"HMCN1 original bytes unchanged");auto old_back=must(decode_continuation_snapshot(old_bytes));check(old_back.continuation_version==1&&old_back.source_identity.execution_epoch==7&&old_back.action_start_tick==1&&old_back.committed_half_days==3&&!old_back.exact_source_moment,"HMCN1 original integer semantics preserved");
    for(const auto& kind:{"travel","long_rest","study_skill"}){auto v=old;v.action_kind=kind;check(encode_continuation_snapshot(v).ok,"HMCN1 finite legacy kinds still supported");}check(!bounded_continuation_kind("service"),"legacy global bounded kind not broadened");old.action_kind="service";check(!encode_continuation_snapshot(old).ok,"HMCN1 cannot encode selected exact service");old=legacy();old.exact_started_at=WorldMoment{};check(!encode_continuation_snapshot(old).ok,"HMCN1 cannot silently drop exact fields");
    for(std::uint8_t n=0;n<=12;++n){auto v=bytes;v.back()=n;auto b=decode_continuation_snapshot(v);check(b.ok&&must(encode_continuation_snapshot(b.value))==v,"explicit RunStop byte closed table round trip");}
    bool all_truncated=true;for(std::size_t n=0;n<bytes.size();++n)if(decode_continuation_snapshot(Bytes(bytes.begin(),bytes.begin()+n)).ok)all_truncated=false;check(all_truncated,"all HMCN2 truncated prefixes rejected");
    auto bad=bytes;bad.push_back(0);check(!decode_continuation_snapshot(bad).ok,"HMCN2 trailing byte rejected");bad=bytes;bad[4]=3;check(!decode_continuation_snapshot(bad).ok,"unknown HMCN version rejected");bad=bytes;bad.back()=13;check(!decode_continuation_snapshot(bad).ok,"unknown u8 stop rejected");bad=bytes;bad[28]=128;check(!decode_continuation_snapshot(bad).ok,"revision unsigned to signed overflow rejected");bad=bytes;patch(bad,independent.maximum,std::uint64_t(1)<<63);check(!decode_continuation_snapshot(bad).ok,"budget unsigned to signed overflow rejected");
    for(auto size:{std::uint64_t(0),std::uint64_t(exact_continuation_snapshot_byte_limit+1),std::numeric_limits<std::uint64_t>::max()}){bad=bytes;patch(bad,independent.source_length,size);check(!decode_continuation_snapshot(bad).ok,"typed leaf bad length rejected before allocation");}bad=bytes;patch(bad,independent.actor_length,257,2);check(!decode_continuation_snapshot(bad).ok,"String256 overlength rejected");bad=bytes;patch(bad,independent.schema,2,4);check(!decode_continuation_snapshot(bad).ok,"unknown Started schema rejected");bad=bytes;bad.resize(exact_continuation_snapshot_byte_limit+1);auto over=decode_continuation_snapshot(bad);check(!over.ok&&over.error.kind==ErrorKind::internal&&over.error.original.code=="ContinuationCapacityExceeded","trusted exact capacity is technical refusal");
    check(!decode_continuation_snapshot(wire(s,moment(2,"2","6")).bytes).ok,"noncanonical source fraction rejected");check(!decode_continuation_snapshot(wire(s,moment(2,"0","7")).bytes).ok,"noncanonical zero rejected");check(!decode_continuation_snapshot(wire(s,moment(2,"1","0")).bytes).ok,"zero denominator rejected");check(!decode_continuation_snapshot(wire(s,moment(2,"1","1")).bytes).ok,"Moment fraction one rejected");check(!decode_continuation_snapshot(wire(s,moment(-1,"1","3")).bytes).ok,"negative typed Moment rejected");check(!decode_continuation_snapshot(wire(s,moment(2,"01","3")).bytes).ok,"fraction leading zero rejected");auto leaf=moment(2,"1","3");leaf.push_back(0);check(!decode_continuation_snapshot(wire(s,leaf).bytes).ok,"typed leaf internal trailing byte rejected");check(!decode_continuation_snapshot(wire(s,moment(2,"1","3"),moment(1,"1","4"),duration("2","4")).bytes).ok,"duration exact typed canonical fraction required");
    auto v=s;v.exact_started_at=WorldMoment{3,{}};check(!encode_continuation_snapshot(v).ok,"scope cannot begin after source");v=s;v.exact_committed_duration=HalfDayDuration{fraction("13","12")};check(encode_continuation_snapshot(v).ok,"committed duration may equal elapsed");v.exact_committed_duration=HalfDayDuration{fraction("14","12")};check(!encode_continuation_snapshot(v).ok,"committed cannot exceed source scope difference");v=s;v.max_half_days=1;v.exact_committed_duration=HalfDayDuration{fraction("13","12")};check(!encode_continuation_snapshot(v).ok,"committed cannot exceed original max");v=s;v.exact_committed_duration=HalfDayDuration{};check(encode_continuation_snapshot(v).ok,"zero committed duration valid");v=s;v.max_gross_outflow=39;check(!encode_continuation_snapshot(v).ok,"gross cannot exceed approval");v=s;v.action_kind="long_rest";check(!encode_continuation_snapshot(v).ok,"HMCN2 selected adapter does not accept old rest");v=s;v.action_started_source.reset();check(!encode_continuation_snapshot(v).ok,"missing actual start ref rejected");v=s;v.exact_committed_duration.reset();check(!encode_continuation_snapshot(v).ok,"missing exact committed duration rejected");
    v=s;v.source_identity.execution_epoch=999;v.action_start_tick=999;v.started_tick=999;v.committed_half_days=999;check(must(encode_continuation_snapshot(v))==bytes,"HMCN2 excludes epoch and integer mirror authority");
    for(const auto& invalid:{std::string("\xc0\x80",2),std::string("\xed\xa0\x80",3),std::string("\xf4\x90\x80\x80",4),std::string("\xe4\xb8",2),std::string("a\0b",3)}){v=s;v.actor_id=invalid;check(!encode_continuation_snapshot(v).ok,"String256 malformed UTF8 or NUL rejected");}v=s;v.actor_id="人物";check(encode_continuation_snapshot(v).ok,"String256 valid UTF8 accepted without normalization");
    v=s;v.exact_committed_duration=HalfDayDuration{fraction("1","1"+std::string(2300,'0')+"7")};auto large=must(encode_continuation_snapshot(v));check(large.size()>continuation_snapshot_byte_limit&&large.size()<exact_continuation_snapshot_byte_limit,"HMCN2 exact leaf not truncated to old 2048");check(!encode_continuation_snapshot(v,continuation_snapshot_byte_limit).ok,"trusted smaller slot cannot truncate exact scope");check(!decode_continuation_snapshot(large,continuation_snapshot_byte_limit).ok,"trusted smaller slot decode refusal");auto large_back=must(decode_continuation_snapshot(large));check(must(compare_fractions(large_back.exact_committed_duration->value,v.exact_committed_duration->value))==0,"large legal denominator preserved exactly");auto legacy_large=old_bytes;legacy_large.resize(continuation_snapshot_byte_limit+1);check(!decode_continuation_snapshot(legacy_large).ok,"HMCN1 retains original 2048 cap");
    std::cout<<"CONTINUATION_EXACT_SNAPSHOT "<<checks<<" checks "<<failures<<" failures\n";return failures?1:0;
}catch(const std::exception& e){std::cerr<<"FAIL exception "<<e.what()<<'\n';return 1;}}
